// NodeLoc Webview 入口。游戏客户端被内联，存档通过用户自己的 KV 同步。

const HTML = "<!DOCTYPE html>\n<html lang=\"zh-CN\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no\">\n  <title>Model Rush</title>\n</head>\n<body class=\"bg-[#0a0a0f] text-white overflow-hidden h-screen w-screen select-none\">\n\n  <!-- 公司名输入覆盖层 -->\n  <div id=\"startup-overlay\" class=\"fixed inset-0 bg-[#0a0a0f] z-[100] flex items-center justify-center\">\n    <div class=\"bg-panel border border-border rounded-xl p-8 w-96 text-center\">\n      <div class=\"text-accent text-2xl font-bold tracking-wider mb-2\">Model Rush</div>\n      <div class=\"text-muted text-sm mb-6\">AI 大模型训练模拟器</div>\n      <div id=\"continue-section\" class=\"mb-4 hidden\">\n        <div class=\"text-xs text-muted mb-2\">选择要继续的存档</div>\n        <div id=\"save-slots-list\" class=\"space-y-1 mb-2\"></div>\n        <div class=\"text-xs text-muted mt-2\">或输入新公司名开始新游戏:</div>\n      </div>\n      <div class=\"text-left mb-4\">\n        <label class=\"text-xs text-muted block mb-1\">公司名称</label>\n        <input id=\"company-name-input\" type=\"text\" class=\"modal-input\" placeholder=\"输入你的AI公司名称...\" maxlength=\"20\" autofocus>\n        <div id=\"company-name-error\" class=\"text-danger text-xs mt-1 hidden\"></div>\n      </div>\n      <div class=\"text-xs text-muted mb-4\">取一个响亮的名字，开始你的AI帝国之旅</div>\n      <button id=\"start-game-btn\" class=\"modal-btn primary w-full py-2\">进入游戏</button>\n    </div>\n  </div>\n\n  <!-- 顶部栏 -->\n  <div id=\"topbar\" class=\"h-12 bg-[#111118] border-b border-border flex items-center px-4 gap-6 text-sm\">\n    <span id=\"company-name-display\" class=\"text-accent font-bold text-base tracking-wide\">Model Rush</span>\n    <span>现金 <span id=\"cash\" class=\"text-accent font-mono\">$500.00M</span></span>\n    <span>市值 <span id=\"valuation\" class=\"text-amber font-mono\">$500.00M</span></span>\n    <span>第 <span id=\"day\" class=\"text-white font-mono\">1</span> 天</span>\n    <span class=\"ml-auto flex gap-1\">\n      <button onclick=\"Game.setSpeed(0)\" id=\"btn-pause\" class=\"speed-btn px-2 py-0.5 rounded border border-border hover:border-accent text-xs\">暂停</button>\n      <button onclick=\"Game.setSpeed(1)\" id=\"btn-1x\" class=\"speed-btn px-2 py-0.5 rounded border border-accent bg-accent/10 text-accent text-xs\">1x</button>\n      <button onclick=\"Game.setSpeed(2)\" id=\"btn-2x\" class=\"speed-btn px-2 py-0.5 rounded border border-border hover:border-accent text-xs\">2x</button>\n    </span>\n  </div>\n\n  <!-- 主体 -->\n  <div id=\"main-body\" class=\"flex\">\n    <!-- 3D 场景 -->\n    <div id=\"scene-container\" class=\"flex-1 relative bg-[#0a0a0f]\">\n      <div id=\"scene-tooltip\" class=\"absolute top-2 left-2 text-xs text-muted bg-panel/80 px-2 py-1 rounded pointer-events-none hidden\"></div>\n      <button id=\"panel-toggle-btn\" onclick=\"UI.toggleMobilePanel()\" aria-label=\"打开信息面板\" aria-expanded=\"false\">☰</button>\n    </div>\n\n    <!-- 拖拽调整手柄 -->\n    <div id=\"panel-resize-handle\" class=\"w-1 bg-border hover:bg-accent cursor-col-resize flex-shrink-0 transition-colors\"></div>\n\n    <!-- 右侧面板 -->\n    <div id=\"right-panel\" class=\"w-80 bg-panel border-l border-border overflow-y-auto flex flex-col text-xs\" style=\"min-width:240px;max-width:500px;\">\n      <!-- 标签栏 -->\n      <div id=\"panel-tabs\" class=\"flex border-b border-border bg-[#111118] sticky top-0 z-10\">\n        <button class=\"panel-tab active\" data-tab=\"finance\">预览</button>\n        <button class=\"panel-tab\" data-tab=\"products\">产品</button>\n        <button class=\"panel-tab\" data-tab=\"training\">训练</button>\n        <button class=\"panel-tab\" data-tab=\"research\">研发</button>\n        <button class=\"panel-tab\" data-tab=\"inventory\">库存</button>\n        <button class=\"panel-tab\" data-tab=\"log\">日志</button>\n      </div>\n\n      <!-- 标签内容 -->\n      <div id=\"tab-content\" class=\"flex-1 overflow-y-auto p-3\">\n        <!-- 预览标签 -->\n        <div class=\"tab-panel active\" data-tab=\"finance\">\n          <div class=\"panel-card mb-2\">\n            <div class=\"text-muted uppercase tracking-wider mb-1\">运营概览</div>\n            <div id=\"overview-summary\" class=\"text-xs space-y-1\"></div>\n          </div>\n          <div class=\"panel-card mb-2\">\n            <div class=\"text-muted uppercase tracking-wider mb-1\">财务</div>\n            <div class=\"grid grid-cols-2 gap-1\">\n              <span class=\"text-muted\">日收入</span><span id=\"panel-income\" class=\"text-accent font-mono text-right\">+$0</span>\n              <span class=\"text-muted\">日支出</span><span id=\"panel-expense\" class=\"text-danger font-mono text-right\">-$0</span>\n              <span class=\"text-muted\">电费（含冷却）</span><span id=\"panel-electricity-expense\" class=\"font-mono text-right\">-$0</span>\n              <span class=\"text-muted\">网费</span><span id=\"panel-network-expense\" class=\"font-mono text-right\">-$0</span>\n              <span class=\"text-muted\">日利润</span><span id=\"panel-profit\" class=\"font-mono text-right\">$0</span>\n              <span class=\"text-muted\">现金</span><span id=\"panel-cash\" class=\"text-accent font-mono text-right\">$500.00M</span>\n            </div>\n          </div>\n          <div class=\"panel-card\">\n            <div class=\"text-muted uppercase tracking-wider mb-1\">基础设施</div>\n            <div class=\"grid grid-cols-2 gap-1\">\n              <span class=\"text-muted\">供电</span><span class=\"font-mono text-right\"><span id=\"panel-power\">0</span>/<span id=\"panel-power-cap\">2</span> MW</span>\n              <span class=\"text-muted\">冷却</span><span class=\"font-mono text-right\"><span id=\"panel-cooling-load\">0</span>/<span id=\"panel-cooling-cap\">3</span> MW</span>\n              <span class=\"text-muted\">GPU总数</span><span id=\"panel-gpu-total\" class=\"font-mono text-right\">0</span>\n              <span class=\"text-muted\">研究员</span><span id=\"panel-researcher\" class=\"font-mono text-right text-accent\">0</span>\n            </div>\n          </div>\n        </div>\n\n        <!-- 产品标签 -->\n        <div class=\"tab-panel\" data-tab=\"products\">\n          <div class=\"panel-card\">\n            <div class=\"text-muted uppercase tracking-wider mb-1\">已部署模型</div>\n            <div id=\"products-list\" class=\"space-y-2\"></div>\n          </div>\n        </div>\n\n        <!-- 训练标签 -->\n        <div class=\"tab-panel\" data-tab=\"training\">\n          <div class=\"panel-card\">\n            <div class=\"text-muted uppercase tracking-wider mb-1\">训练状态</div>\n            <div id=\"training-status\" class=\"text-muted italic\">暂无训练任务</div>\n            <div id=\"training-progress\" class=\"hidden mt-1\">\n              <div class=\"flex justify-between text-xs\"><span id=\"training-phase\"></span><span id=\"training-pct\"></span></div>\n              <div class=\"progress-bar mt-1\"><div id=\"training-bar\" class=\"progress-fill\" style=\"width:0%\"></div></div>\n              <div id=\"training-eta\" class=\"text-muted mt-1\"></div>\n              <div id=\"training-detail\" class=\"hidden mt-2 grid grid-cols-2 gap-1 text-xs\">\n                <span class=\"text-muted\">子阶段</span><span id=\"train-sub-phase\" class=\"font-mono text-right\">--</span>\n                <span class=\"text-muted\">Loss</span><span id=\"train-loss\" class=\"font-mono text-right\">--</span>\n                <span class=\"text-muted\">GPU利用率</span><span id=\"train-gpu-util\" class=\"font-mono text-right\">--</span>\n                <span class=\"text-muted\">稳定性</span><span id=\"train-stability\" class=\"font-mono text-right\">--</span>\n                <span class=\"text-muted\">检查点</span><span id=\"train-checkpoints\" class=\"font-mono text-right\">0</span>\n                <span id=\"train-event\" class=\"text-danger text-right hidden\"></span>\n              </div>\n              <button id=\"abandon-train-btn\" class=\"action-btn danger-btn text-xs mt-2 hidden\" onclick=\"Training.abandonTraining()\">放弃训练</button>\n            </div>\n          </div>\n        </div>\n\n        <!-- 研发标签 -->\n        <div class=\"tab-panel\" data-tab=\"research\">\n          <div class=\"panel-card mb-2\">\n            <div class=\"text-muted uppercase tracking-wider mb-1\">研发进度</div>\n            <div id=\"research-progress\" class=\"space-y-1\"></div>\n          </div>\n          <div class=\"panel-card\">\n            <div class=\"text-muted uppercase tracking-wider mb-1\">已解锁技术</div>\n            <div id=\"unlocked-techs\" class=\"space-y-0.5\"></div>\n          </div>\n        </div>\n\n        <!-- 库存标签 -->\n        <div class=\"tab-panel\" data-tab=\"inventory\">\n          <div class=\"panel-card\">\n            <div class=\"text-muted uppercase tracking-wider mb-1\">GPU 库存</div>\n            <div id=\"gpu-inventory\" class=\"space-y-0.5\"></div>\n          </div>\n        </div>\n\n        <!-- 日志标签 -->\n        <div class=\"tab-panel\" data-tab=\"log\">\n          <div class=\"panel-card h-full\">\n            <div class=\"text-muted uppercase tracking-wider mb-1\">事件日志</div>\n            <div id=\"event-log\" class=\"space-y-0.5 overflow-y-auto\" style=\"max-height: calc(100vh - 230px);\"></div>\n          </div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- 底部操作栏 -->\n  <div id=\"bottombar\" class=\"h-12 bg-[#111118] border-t border-border flex items-center px-4 gap-2\">\n    <!-- GPU 管理 -->\n    <div class=\"dropdown-group\">\n      <button class=\"action-btn dropdown-toggle\" onclick=\"UI.toggleDropdown(this)\">GPU 管理</button>\n      <div class=\"dropdown-menu\">\n        <button onclick=\"UI.showModal('buy-gpu');UI.closeDropdown()\" class=\"dropdown-item\">购买 GPU</button>\n        <button onclick=\"UI.showModal('demolish-gpu');UI.closeDropdown()\" class=\"dropdown-item\">拆除 GPU</button>\n      </div>\n    </div>\n    <!-- 基础设施 -->\n    <div class=\"dropdown-group\">\n      <button class=\"action-btn dropdown-toggle\" onclick=\"UI.toggleDropdown(this)\">基础设施</button>\n      <div class=\"dropdown-menu\">\n        <button onclick=\"UI.showModal('expand-power');UI.closeDropdown()\" class=\"dropdown-item\">扩容供电</button>\n        <button onclick=\"UI.showModal('expand-cooling');UI.closeDropdown()\" class=\"dropdown-item\">扩容冷却</button>\n        <button onclick=\"UI.showModal('expand-datacenter');UI.closeDropdown()\" class=\"dropdown-item\">扩容机房</button>\n      </div>\n    </div>\n    <!-- 团队 -->\n    <div class=\"dropdown-group\">\n      <button class=\"action-btn dropdown-toggle\" onclick=\"UI.toggleDropdown(this)\">团队</button>\n      <div class=\"dropdown-menu\">\n        <button onclick=\"UI.showModal('hire-researcher');UI.closeDropdown()\" class=\"dropdown-item\">聘请研究员</button>\n        <button onclick=\"UI.showModal('research');UI.closeDropdown()\" class=\"dropdown-item\">研发技术</button>\n      </div>\n    </div>\n    <button onclick=\"UI.showModal('collect-data')\" class=\"action-btn\">采集数据</button>\n    <button onclick=\"UI.showModal('new-training')\" class=\"action-btn\">新建训练</button>\n    <button onclick=\"Economy.fundraise()\" class=\"action-btn\" id=\"btn-fundraise\">发起融资</button>\n    <button onclick=\"UI.startTutorial(true)\" class=\"action-btn\">新手引导</button>\n    <span class=\"text-muted mx-1\">|</span>\n    <button onclick=\"SaveSystem.save(false)\" class=\"action-btn\">保存游戏</button>\n    <button onclick=\"UI.showModal('save-manager')\" class=\"action-btn\">存档管理</button>\n    <button onclick=\"UI.showDeleteConfirm()\" class=\"action-btn text-danger hover:border-danger\">删除存档</button>\n  </div>\n\n  <!-- beta-only:project-footer:start -->\n  <footer id=\"project-footer\">\n    <a href=\"https://github.com/mukunjin/model-rush\" target=\"_blank\" rel=\"noopener noreferrer\">正式版仓库</a>\n    <a href=\"https://github.com/hekuo5310/model-rush-beta\" target=\"_blank\" rel=\"noopener noreferrer\">测试版仓库</a>\n  </footer>\n  <!-- beta-only:project-footer:end -->\n\n  <!-- 模态框容器 -->\n  <div id=\"modal-overlay\" class=\"hidden fixed inset-0 bg-black/60 z-50 flex items-center justify-center\">\n    <div id=\"modal-content\" class=\"bg-panel border border-border rounded-lg p-5 max-w-lg w-full max-h-[80vh] overflow-y-auto\"></div>\n  </div>\n\n  <!-- Toast -->\n  <div id=\"toast\" class=\"hidden fixed top-16 right-4 bg-panel border border-accent rounded px-4 py-2 text-sm z-50 shadow-lg\"></div>\n\n  <!-- 禁用 Cloudflare Rocket Loader 对游戏脚本的延迟改写，保证启动事件按顺序绑定。 -->\n  </body>\n</html>\n";
